def load_codexpro_full_tool_contract() -> list[dict[str, Any]]:
    value = json.loads(_CODEXPRO_FULL_TOOL_CONTRACT_JSON)
    if not isinstance(value, list) or len(value) != CODEXPRO_FULL_TOOL_COUNT:
        raise RuntimeError("embedded CodexPro Hub tool contract is corrupted")
    return [dict(item) for item in value if isinstance(item, dict)]

